def run(context):
    hits = [s for s in context['signal_data'] if s['hit_target'] or s['hit_stop']]
    summary = {'total': len(hits), 'successful_hits': len([s for s in hits if s['hit_target']]), 'failed_hits': len([s for s in hits if s['hit_stop']])}
    return {'analysis_summary': summary}

def run(context):
    # Process the report data for validation
    report_data = context['report_data']
    validation_summary = {
        'broken_links': [],
        'missing_data': []
    }
    # Identify and log validation issues
    for report in report_data:
        if not report.get('link'):
            validation_summary['broken_links'].append(report)
        if not report.get('data'): 
            validation_summary['missing_data'].append(report)
    return validation_summary

